mapper.codeEditorJavascript:
const p=v=>typeof v==='string'?JSON.parse(v):v;
const out=[];
const BAD=/פעיל|מוטרד|הסר|הסיר|אל תתקשר|לא להתקשר|תשתית|כבר לקוח|לקוח קיים|חסום/;
for(const a of (p(input.arr)||[])){let b={};try{b=JSON.parse(a.j)}catch(e){}
const act=b.activeLeads||[];const inact=b.inactiveCampaigns||[];
const why=[];
const fu=act.filter(l=>/FOLLOW/i.test(String(l.status||'')));
if(fu.length)why.push('פולואפ פתוח: '+fu.map(l=>(l.followByName||'')+' '+String(l.campaignName||'')).join(', '));
if(act.some(l=>String(l.campaignName||'').trim()==='הזדמנות שניה'))why.push('כבר בקמפיין הזדמנות שניה');
const sale=inact.filter(l=>String(l.reason||'').toUpperCase()==='CLOSED');
if(sale.length)why.push('עסקה נסגרה: '+sale.map(l=>(l.agentName||'')+' '+String(l.timestamp||'').slice(0,10)).join(', '));
const bad=inact.filter(l=>BAD.test(String((l.subReason&&l.subReason.name)||'')+' '+String(l.note||'')));
if(bad.length)why.push('סטטוס חוסם: '+bad.map(l=>(l.subReason&&l.subReason.name)||'').join(', '));
const last=inact.slice().sort((x,y)=>String(y.timestamp).localeCompare(String(x.timestamp)))[0];
out.push({p:a.p,ok:!why.length,why:why.join(' | '),last:last?((last.reason||'')+'/'+((last.subReason&&last.subReason.name)||'')+'/'+(last.agentName||'')+'/'+String(last.timestamp||'').slice(0,16)):'',act:act.map(l=>l.campaignName+':'+l.status).join(',')});}
return JSON.stringify(out);
